import java.util.Scanner;
public class JCheckProductCode2 {
	public static void main(String[] args) {
		JCheckProductCode2 p2 = new JCheckProductCode2();
		p2.checkProductCode();
	}
	//Paso 1: Definir el metodo
	public void checkProductCode() {
		//Paso 1.1: Definir las variables que necesitamos para los contadores
	    int valid = 0;
	    int banned = 0;
	    //Paso 1.2: Solicitar una entrada valida mientras el usuario no escriba STOP; de lo contrario, terminar
		Scanner scan = new Scanner(System.in);
		System.out.println("Ingrese codigo de producto:");
		String code = scan.next();	    
	    while ( ! code.equals("STOP") ) {
	    	 //Paso 1.2.1: Encerrar el codigo que podria lanzar una excepcion dentro del bloque try
	        try {
	            char zone = code.charAt(9);
	            int district = Integer.parseInt(code.substring(3, 7));
	            valid += 1;
	            if (zone == 'R' && district >= 2000) {
	                banned += 1;
	            }
	        }
	        //Paso 1.2.2: Manejar todas las excepciones posibles que puedan ser lanzadas en el bloque try
	       catch (IndexOutOfBoundsException ex ) {                    
	            System.out.println("Longitud de codigo incorrecta.");
	       } 
		catch (NumberFormatException ex ) {                   
			System.out.println("Error! Distrito no es numerico.");
		}
			System.out.println("Ingrese codigo de producto:");
			code = scan.next();
	    }
	    //Paso 1.3: Imprimir el resultado    
	    System.out.println("# de codigos validos ingresados: " + valid);
	    System.out.println("# de codigos prohibidos ingresados: "+ banned);
	}
}

